// GENERATED by agentArena/bots/build.mjs from bots/core.js and bots/bedwars.game.js: edit those, then build.

// The house bots' shared core (agentArena/bots/README.md): helpers over the arena's bot API, safe bridging, walking,
// combat reflexes, and the planner's search engine. Not a strategy by itself: bots/build.mjs puts it in front of each
// game's file (bots/<game>.game.js) to make the self-contained strategy the arena runs (bots/<game>.js).
//
// Lessons of the Gemini-vs-DeepSeek runs (agentArena/runs/gemini-vs-deepseek-sw*) built in here:
// - Rounds were lost to falls, not fights: a bridge stepped past its last block (sw3), a sneak at an island's edge (sw1).
//   So every bridge block is placed from the centre of the block below; a step forward follows only a placement seen in
//   the world; the bot sneaks the whole time it bridges, steps in taps (the arena delays every press and release by
//   about 0.28 s, so a held key overshoots), and walks islands with the pathfinder, which keeps off edges.
// - The fights that decided rounds (sw2, sw4) were won by sprint hits at the attack cooldown, with a golden apple when
//   hurt: kept, with a sprint reset (W-tap) before each hit for full knockback.
// - From CreepyNightmares/BedwarsPracticeBot (CombatEngine, aiConfig.yml): lead a moving target (look, approach and
//   arrows aimed where the player will be; every action here arrives a reaction time late), an S-tap after a hit at close
//   range, a strafe between hits on wide ground, back off when hurt and outmatched with nothing to eat, and never a
//   teammate as the target. Its crit jumps are left out: this game's guest attacks are never critical.

const BLOCK_RE = /(planks|wool|stone$|cobblestone|dirt|terracotta|sandstone|concrete|end_stone|^glass$|_log$|andesite|diorite|granite|deepslate|bricks)$/;
const NOT_BLOCK = /(sword|pickaxe|_axe|shovel|hoe|helmet|chestplate|leggings|boots|bow|arrow|apple|pearl|bucket|egg|snowball|stick|potion|ingot|diamond$|emerald$)/;
const SWORD = { wooden_sword: 4, golden_sword: 4, stone_sword: 5, iron_sword: 6, diamond_sword: 7, netherite_sword: 8 };
const AXE = { wooden_axe: 3, golden_axe: 3, stone_axe: 4, iron_axe: 5, diamond_axe: 6 };
const ARMOR_TIER = { leather: 1, golden: 2, chainmail: 3, iron: 4, diamond: 5, netherite: 6 };
const ARMOR_SLOT = [['helmet', 'head'], ['chestplate', 'torso'], ['leggings', 'legs'], ['boots', 'feet']];
const ATTACK_MS = 600;            // a sword's cooldown (Java: 0.625 s)

const log = (...a) => console.log('[house]', ...a);
const items = (bot) => { try { return bot.inventory.items() || []; } catch { return []; } };
const isBlock = (it) => it && it.count > 0 && BLOCK_RE.test(it.name) && !NOT_BLOCK.test(it.name);
const blockCount = (bot) => items(bot).filter(isBlock).reduce((n, it) => n + it.count, 0);
const weaponScore = (it) => (it ? SWORD[it.name] ?? AXE[it.name] ?? 0 : 0);
const v = (p) => new Vec3(p.x, p.y, p.z);
const solid = (bot, p) => { const b = bot.blockAt(p); return !!b && b.boundingBox === 'block'; };
const feetCell = (bot) => bot.entity.position.offset(0, -0.5, 0).floored();
const withTimeout = (p, ms) => Promise.race([p, sleep(ms).then(() => 'timeout')]).catch((e) => e);

/** A teammate (Bed Wars with more than one player a team): the arena's player list says who is on which team. */
function teammate(bot, name) {
  const me = bot.arena && bot.arena.me, list = (bot.arena && bot.arena.players) || [];
  if (!me || !me.team) return false;
  const p = list.find((q) => q.name === name);
  return !!p && p.team === me.team;
}

function enemy(bot, { heard = false } = {}) {
  noteMotion(bot);
  return bot.nearestEntity((e) => e.type === 'player' && e.username !== bot.username && (heard || !e.heard) && !teammate(bot, e.username));
}

// Where each player in sight was over the last 0.6 s, for their velocity. Every look and every key press arrives a
// reaction time (0.15-0.21 s) after the bot decides it, and an arrow flies for a while: aimed at where a running player
// is now, both land behind them. (After CreepyNightmares/BedwarsPracticeBot, CombatEngine.predictMovement.)
const motion = new Map();
function noteMotion(bot) {
  const now = Date.now();
  let ents;
  try { ents = Object.values(bot.entities); } catch { return; }
  for (const e of ents) {
    if (!e || e.type !== 'player' || e.heard || e.username === bot.username) continue;
    const list = motion.get(e.username) || [];
    if (list.length && now - list[list.length - 1].t < 40) continue;
    list.push({ t: now, x: e.position.x, z: e.position.z });
    while (list.length > 2 && now - list[0].t > 600) list.shift();
    motion.set(e.username, list);
  }
}
/** A player's ground velocity in blocks a second (0 when not seen moving lately); capped at a sprint's speed (a knock-back is faster, and is not where they are going). */
function velocityOf(foe) {
  const list = motion.get(foe.username);
  if (!list || list.length < 2) return { x: 0, z: 0 };
  const a = list[0], b = list[list.length - 1], dt = (b.t - a.t) / 1000;
  if (dt < 0.1 || Date.now() - b.t > 500) return { x: 0, z: 0 };
  let x = (b.x - a.x) / dt, z = (b.z - a.z) / dt;
  const s = Math.hypot(x, z);
  if (s > 5.6) return { x: 0, z: 0 };
  return { x, z };
}
/** Where a player will be in `s` seconds if they keep going as they go. */
function predict(foe, s) { const vel = velocityOf(foe); return foe.position.offset(vel.x * s, 0, vel.z * s); }

async function holdBlock(bot) {
  if (isBlock(bot.heldItem)) return true;
  const best = items(bot).filter(isBlock).sort((a, b) => b.count - a.count)[0];
  if (!best) return false;
  try { await bot.equip(best, 'hand'); } catch { return false; }
  return true;
}

async function holdWeapon(bot) {
  const best = items(bot).sort((a, b) => weaponScore(b) - weaponScore(a))[0];
  if (!best || weaponScore(best) === 0 || (bot.heldItem && bot.heldItem.name === best.name)) return;
  try { await bot.equip(best, 'hand'); } catch { /* next time */ }
}

async function wearBestArmour(bot) {
  for (const [piece, dest] of ARMOR_SLOT) {
    const worn = bot.inventory.slots[{ head: 5, torso: 6, legs: 7, feet: 8 }[dest]];
    const tier = (it) => (it ? ARMOR_TIER[it.name.split('_')[0]] ?? 0 : 0);
    const best = items(bot).filter((it) => it.name.endsWith(`_${piece}`)).sort((a, b) => tier(b) - tier(a))[0];
    if (best && tier(best) > tier(worn)) { try { await bot.equip(best, dest); log('wearing', best.name); } catch { /* next time */ } }
  }
}

/**
 * Walk on the ground there is (the pathfinder keeps off edges); false if there is no walking route, or if a threat
 * comes up on the way (hit, or a player seen or heard within 6 blocks): a walk never keeps the bot from reacting.
 */
async function walkTo(bot, p, range = 1.5, ms = 12000, { interrupt = true } = {}) {
  let failed = false;
  const going = bot.pathfinder.goto(new goals.GoalNear(p.x, p.y, p.z, range)).then(() => 'done', () => { failed = true; return 'failed'; });
  let outcome = null;
  going.then((r) => { outcome = r; });
  const until = Date.now() + ms;
  while (outcome === null && Date.now() < until) {
    // 'hit': only a hit stops it (a hunt: the player near is the one it is after, but a hit from behind is not).
    if (interrupt === 'hit' ? Date.now() - awareness.hurtAt < 1500 || closeEnoughToHit(bot) : interrupt && threatened(bot, 6)) { bot.pathfinder.stop(); return false; }
    await bot.waitForTicks(2);
  }
  bot.pathfinder.stop();
  return outcome === 'done' && !failed;
}

/**
 * The block I stand on. Sneaking at an edge can leave my centre over air with my feet still on a block beside it;
 * that block is the one under the corner of my box nearest my centre.
 */
function standingCell(bot) {
  const p = bot.entity.position, under = feetCell(bot);
  if (solid(bot, under)) return under;
  const cells = [[-0.3, -0.3], [-0.3, 0.3], [0.3, -0.3], [0.3, 0.3]].map(([dx, dz]) => new Vec3(Math.floor(p.x + dx), under.y, Math.floor(p.z + dz)));
  return cells.filter((c) => solid(bot, c)).sort((a, b) => p.xzDistanceTo(a.offset(0.5, 0, 0.5)) - p.xzDistanceTo(b.offset(0.5, 0, 0.5)))[0] || null;
}

/**
 * Walk to the middle of a block's top, sneaking, in taps: the arena delays every press and release alike (150-210 ms),
 * so a held key overshoots by a quarter of a block; a tap stays a tap.
 */
async function stepTo(bot, cell, within = 0.2) {
  const goal = cell.offset(0.5, 1, 0.5);
  const quick = instant(bot);
  bot.setControlState('sneak', !quick);
  let aimed = null;
  const since = Date.now();
  const hit = () => awareness.hurtAt > since; // knocked about: stop stepping, the caller reacts
  for (let i = 0; i < 40 && !hit(); i++) {
    const p = bot.entity.position, d = p.xzDistanceTo(goal);
    if (d <= within) break;
    // Aim at the goal once, and again only if it has moved off to the side of where I face (each look costs a reaction).
    const yaw = Math.atan2(-(goal.x - p.x), -(goal.z - p.z));
    if (aimed === null || Math.abs(Math.atan2(Math.sin(yaw - aimed), Math.cos(yaw - aimed))) > 0.35) { await bot.look(yaw, -0.3); aimed = yaw; }
    if (d > 0.6) {
      // Far: hold forward (sneaking holds me at any edge) until the delayed release will land me about on the middle.
      bot.setControlState('forward', true);
      while (bot.entity.position.xzDistanceTo(goal) > (quick ? 0.3 : 0.38) && i++ < 40 && !hit()) await bot.waitForTicks(1);
      bot.setControlState('forward', false);
      await bot.waitForTicks(quick ? 1 : 4); // the release arrives after the reaction time (150-210 ms), or at once
    } else {
      bot.setControlState('forward', true);
      await bot.waitForTicks(1);
      bot.setControlState('forward', false);
      await bot.waitForTicks(1);
    }
  }
}

/** Step to the centre of the block I stand on: the only place a bridge block is placed from. */
async function centre(bot) {
  const cell = standingCell(bot);
  if (cell) await stepTo(bot, cell);
}

/**
 * Bridge toward `target` (a point), flat, from the island I stand on. Sneaking throughout; each block placed from the
 * centre of the block below me against its side; a step forward only onto a block that is there.
 * @returns 'arrived' | 'enemy' | 'no_blocks' | 'fell' | 'stuck'
 */
async function bridgeTo(bot, target, { stopForEnemy = true, arrive = 2.5 } = {}) {
  const startY = bot.entity.position.y;
  let fails = 0, best = Infinity, bestAt = 0, placed = 0;
  const startedAt = Date.now();
  bot.setControlState('sneak', !instant(bot));
  try {
    for (let guard = 0; guard < 400; guard++) {
      if (bot.entity.position.y < startY - 2.5) { await pearlClutch(bot, bridgeMem); return 'fell'; }
      const dist = bot.entity.position.xzDistanceTo(target);
      if (dist <= arrive) return 'arrived';
      // No closer for 3 seconds: something in the way that this loop cannot solve; let the plan choose again.
      if (dist < best - 0.3) { best = dist; bestAt = guard; } else if (guard - bestAt > 60) return 'stuck';
      // Hit (an arrow, a punch): stop at once; the caller reacts (reactToThreat).
      if (awareness.hurtAt > startedAt && Date.now() - awareness.hurtAt < 1500) return 'hit';
      // A player close by, seen within 4.5 or heard within 8: stop, and let the caller deal with them.
      const foe = enemy(bot, { heard: true });
      if (near16(bot, foe)) awareness.threatAt = Date.now();
      if (foe && stopForEnemy && bot.entity.position.distanceTo(foe.position) <= (foe.heard ? 8 : 4.5)) return 'enemy';
      // Even on a hunt: a foe in sight close enough to hit me ends the bridging (a hit on a bridge is a fall).
      if (foe && closeEnoughToHit(bot, foe)) return 'enemy';
      let here = feetCell(bot);
      if (!solid(bot, here)) {
        // Over the edge with my centre: back onto the block my feet are on.
        const cell = standingCell(bot);
        if (!cell) { await bot.waitForTicks(2); continue; } // in the air: landing, or falling
        await stepTo(bot, cell);
        here = feetCell(bot);
        if (!solid(bot, here)) continue;
      }
      const dx = target.x - (here.x + 0.5), dz = target.z - (here.z + 0.5);
      const step = Math.abs(dx) > Math.abs(dz) ? new Vec3(Math.sign(dx), 0, 0) : new Vec3(0, 0, Math.sign(dz));
      const next = here.plus(step);
      // Ground ahead already (an island, not my bridge): with something at body height in the way (a lamp post, a
      // tree), or simply on land again, the pathfinder walks the rest, round whatever stands there.
      if (solid(bot, next) && (solid(bot, next.offset(0, 1, 0)) || solid(bot, next.offset(0, 2, 0)) || solid(bot, next.plus(step)))) {
        // On land: walk (not bridge) to the far edge of it along the way to the target -- round anything in the way --
        // and bridge on from there. If the target is on this land, that walk arrives.
        const edge = launchPoint(bot, target);
        if (!edge.equals(here)) {
          bot.setControlState('sneak', false);
          await walkTo(bot, edge.offset(0.5, 1, 0.5), 0.8, 8000, { interrupt: stopForEnemy });
          bot.setControlState('sneak', !instant(bot));
          continue;
        }
      }
      if (!solid(bot, next)) {
        if (!(await holdBlock(bot))) return 'no_blocks';
        // Placed from the middle of the block below me (never from its edge, where the new block would be inside me).
        if (bot.entity.position.xzDistanceTo(here.offset(0.5, 0, 0.5)) > 0.3) await centre(bot);
        try { await bot.placeBlock(bot.blockAt(here), step); fails = 0; } catch (e) {
          fails++;
          if (fails >= 4) return 'stuck';
          await bot.waitForTicks(2);
          continue;
        }
        await bot.waitForTicks(1);
        if (!solid(bot, next)) continue; // not there (yet): never step onto air
        placed++;
      }
      // Onto the next block, sneaking, in taps, until I stand over its middle.
      await stepTo(bot, next, 0.25);
      // With an enemy about, rails: a block either side of the one I stand on, so a hit is less likely to send me over.
      if (Date.now() - awareness.threatAt < 20000 && blockCount(bot) > 12) {
        const side = new Vec3(step.z, 0, -step.x);
        for (const s of [side, new Vec3(-side.x, 0, -side.z)]) {
          if (solid(bot, next.plus(s))) continue;
          try { await bot.placeBlock(bot.blockAt(next), s); } catch { /* out of reach, or not allowed: go on */ }
        }
      }
      // A look behind every five blocks: what I can see is what I face, and a bridge is crossed facing down and ahead.
      if (placed > 0 && placed % 5 === 0 && !instant(bot)) {
        await bot.look(bot.entity.yaw + Math.PI, 0);
        await bot.waitForTicks(2);
        const behind = enemy(bot);
        if (behind && near16(bot, behind)) awareness.threatAt = Date.now();
        if (behind) { if (stopForEnemy && bot.entity.position.distanceTo(behind.position) < 25) return 'enemy'; }
      }
    }
    return 'stuck';
  } finally {
    bot.setControlState('forward', false);
    bot.setControlState('sneak', false);
  }
}

const near16 = (bot, foe) => !!foe && bot.entity.position.distanceTo(foe.position) < 16;
/**
 * No reaction delay under my rules (the MCP autopilot's standard): a press and a release land on the tick they are
 * made, so a step can walk (not sneak) and stop on the spot -- three times the pace of a sneak.
 */
const instant = (bot) => !!(bot.arena && bot.arena.rules && bot.arena.rules.reactionMs === 0);

/** My reach under the rules I play by (bot.arena.rules), 4 blocks if not given. */
const reachOf = (bot) => (bot.arena && bot.arena.rules && bot.arena.rules.reach) || 4;
/** A foe in sight near enough to hit me (my reach and 1.5 blocks more: their step in): time to fight, not to build. */
function closeEnoughToHit(bot, foe = enemy(bot)) {
  return !!foe && !foe.heard && bot.entity.position.distanceTo(foe.position) <= reachOf(bot) + 1.5;
}

/** Memory for a pearl thrown from inside a long move (bridgeTo has no mem of its own). */
const bridgeMem = {};

/** What the bot has noticed lately: when it was last hurt, when it last saw or heard an enemy, the last wide ground. */
const awareness = { hurtAt: 0, threatAt: 0, lastLand: null, lastHealth: 20 };

/** Listen for hurts (and health drops: an arrow from someone unseen), once per program start. */
function watchForHits(bot) {
  bot.on('entityHurt', (e) => { if (e && (e === bot.entity || e.username === bot.username)) awareness.hurtAt = Date.now(); });
  bot.on('health', () => { if (bot.health < awareness.lastHealth - 0.01) awareness.hurtAt = Date.now(); awareness.lastHealth = bot.health; });
}

/**
 * Whether a long move (farming, looting, covering a bed) should stop for a threat: hit in the last 1.5 s, or a player
 * seen or heard within `range` blocks. A player behind me is only heard; hitting me from there must still stop me.
 */
function threatened(bot, range = 10) {
  if (Date.now() - awareness.hurtAt < 1500) return true;
  const foe = enemy(bot, { heard: true });
  if (near16(bot, foe)) awareness.threatAt = Date.now();
  return !!foe && bot.entity.position.distanceTo(foe.position) < range;
}

const hasBow = (bot) => items(bot).some((it) => it.name === 'bow') && bot.inventory.count('arrow') > 0;

// --- ranged play: arrows, snowballs and eggs, ender pearls ---------------------------------------------------------
// Each kind flies as vanilla moves it (the Minecraft Wiki's Arrow, Snowball, Ender Pearl): an arrow at 3 blocks a tick
// at full draw (a second), a thrown item at 1.5; each keeps 99% of its speed a tick and falls 0.05 (arrow) or 0.03.
const PHYS = { arrow: { speed: 3, gravity: 0.05 }, snowball: { speed: 1.5, gravity: 0.03 }, egg: { speed: 1.5, gravity: 0.03 }, ender_pearl: { speed: 1.5, gravity: 0.03 } };
const EYE = 1.52;   // where a shot leaves, above the feet
const reactionS = (bot) => (((bot.arena && bot.arena.rules && bot.arena.rules.reactionMs) || 0) + 30) / 1000;

/** The pitch (low arc) that brings a shot `h` blocks out at `dy` above where it left, and the ticks it takes; null when out of range. */
function aimPitch(kind, h, dy) {
  const P = PHYS[kind];
  const at = (pitch) => {
    let x = 0, y = 0, vx = Math.cos(pitch) * P.speed, vy = Math.sin(pitch) * P.speed;
    for (let t = 1; t <= 100; t++) {
      if (x + vx >= h) { const k = (h - x) / vx; return { y: y + vy * k, ticks: t - 1 + k }; }
      x += vx; y += vy; vx *= 0.99; vy = vy * 0.99 - P.gravity;
    }
    return null;
  };
  let lo = -1.45, hi = 1.45, best = null;
  for (let i = 0; i < 30; i++) {
    const mid = (lo + hi) / 2, r = at(mid);
    if (!r) { if (mid > 0.6) hi = mid; else lo = mid; continue; }
    if (r.y < dy) lo = mid; else { hi = mid; best = { pitch: mid, ticks: r.ticks }; }
  }
  return best;
}

/** The steep (lob) pitch that brings a shot `h` out at `dy`: over cover the flat one would strike. Null when none. */
function lobPitch(kind, h, dy) {
  const P = PHYS[kind];
  for (let pitch = 1.4; pitch > 0.6; pitch -= 0.01) {
    let x = 0, y = 0, vx = Math.cos(pitch) * P.speed, vy = Math.sin(pitch) * P.speed;
    for (let t = 1; t <= 100; t++) {
      if (x + vx >= h) { const k = (h - x) / vx, yy = y + vy * k; if (Math.abs(yy - dy) < 0.4 && vy < 0) return { pitch, ticks: t - 1 + k }; break; }
      x += vx; y += vy; vx *= 0.99; vy = vy * 0.99 - P.gravity;
    }
  }
  return null;
}

/** Look so that a `kind` shot meets the foe: where they will be when it arrives (my reaction and its flight). False when out of range. */
async function aimShot(bot, foe, kind) {
  noteMotion(bot);
  const now = bot.entities[foe.id] || foe;
  const eye = bot.entity.position.offset(0, EYE, 0);
  let ticks = 0, aim = null;
  for (let i = 0; i < 3; i++) {
    const p = predict(now, reactionS(bot) + ticks / 20);
    const h = Math.hypot(p.x - eye.x, p.z - eye.z);
    const a = aimPitch(kind, h, p.y + 1.0 - eye.y); // the middle of the body
    if (!a) return false;
    ticks = a.ticks;
    aim = { yaw: Math.atan2(-(p.x - eye.x), -(p.z - eye.z)), pitch: a.pitch };
  }
  if (!clearFlight(bot, kind, eye, aim, ticks)) {
    // Cover in the way of the flat shot: a lob over it, if one lands on them (it flies longer: lead again).
    const p0 = predict(now, reactionS(bot) + ticks / 20);
    const h0 = Math.hypot(p0.x - eye.x, p0.z - eye.z);
    const lob = lobPitch(kind, h0, p0.y + 1.0 - eye.y);
    if (!lob) return false;
    const p = predict(now, reactionS(bot) + lob.ticks / 20);
    const l2 = lobPitch(kind, Math.hypot(p.x - eye.x, p.z - eye.z), p.y + 1.0 - eye.y) || lob;
    const high = { yaw: Math.atan2(-(p.x - eye.x), -(p.z - eye.z)), pitch: l2.pitch };
    if (!clearFlight(bot, kind, eye, high, l2.ticks)) return false;
    await bot.look(high.yaw, high.pitch);
    return true;
  }
  await bot.look(aim.yaw, aim.pitch);
  return true;
}

/** Whether a shot along `aim` from `eye` flies `ticks` ticks without striking a block (it would end there). */
function clearFlight(bot, kind, eye, aim, ticks) {
  const P = PHYS[kind];
  let x = eye.x, y = eye.y, z = eye.z;
  let vx = -Math.sin(aim.yaw) * Math.cos(aim.pitch) * P.speed, vy = Math.sin(aim.pitch) * P.speed, vz = -Math.cos(aim.yaw) * Math.cos(aim.pitch) * P.speed;
  for (let t = 0; t < Math.min(100, ticks - 0.5); t++) {
    for (let k = 1; k <= 4; k++) if (solid(bot, new Vec3(Math.floor(x + (vx * k) / 4), Math.floor(y + (vy * k) / 4), Math.floor(z + (vz * k) / 4)))) return false;
    x += vx; y += vy; z += vz; vx *= 0.99; vy = vy * 0.99 - P.gravity; vz *= 0.99;
  }
  return true;
}

/** One arrow at a foe: draw a full second, keeping the aim on where they will be, and loose. */
async function shoot(bot, foe) {
  const bow = items(bot).find((it) => it.name === 'bow');
  if (!bow || bot.inventory.count('arrow') < 1) return false;
  try {
    bot.clearControlStates();
    await bot.equip(bow, 'hand');
    if (!(await aimShot(bot, foe, 'arrow'))) return false;
    bot.activateItem();
    for (let i = 0; i < 4; i++) { await bot.waitForTicks(5); await aimShot(bot, foe, 'arrow'); }
    await bot.waitForTicks(1);
    bot.deactivateItem();
    log('arrow at', foe.username, bot.entity.position.distanceTo(foe.position).toFixed(1));
    return true;
  } catch { try { bot.deactivateItem(); } catch { /* not drawn */ } return false; }
}

const throwable = (bot) => items(bot).find((it) => it.name === 'snowball' || it.name === 'egg');

/** A snowball or an egg at a foe: no damage, but the knock-back takes a player on a bridge into the void. */
async function throwAt(bot, foe, mem) {
  const it = throwable(bot);
  if (!it || Date.now() - (mem.thrownAt || 0) < 550) return false; // a player hit is immune for half a second
  try {
    bot.clearControlStates();
    await bot.equip(it, 'hand');
    if (!(await aimShot(bot, foe, it.name))) return false;
    bot.activateItem();
    mem.thrownAt = Date.now();
    log(it.name, 'at', foe.username, bot.entity.position.distanceTo(foe.position).toFixed(1));
    return true;
  } catch { return false; }
}

/**
 * Pillar up `levels` blocks where I stand: look straight down, jump, and at the top of the jump place a block in the
 * cell I left, landing on it (the speed-pillar of SkyWars guides). Reaches a foe standing above me, or high ground over
 * one below. Returns how many blocks it placed.
 */
async function pillarUp(bot, levels = 1) {
  if (!(await holdBlock(bot))) return 0;
  bot.clearControlStates();
  await bot.look(bot.entity.yaw, -Math.PI / 2);
  let placed = 0;
  for (let i = 0; i < levels; i++) {
    const feet = bot.entity.position.floored();
    if (solid(bot, feet.offset(0, 2, 0)) || !solid(bot, feet.offset(0, -1, 0))) break; // a ceiling, or no floor to stand on
    bot.setControlState('jump', true);
    let up = false;
    for (let t = 0; t < 12; t++) { await bot.waitForTicks(1); if (bot.entity.position.y >= feet.y + 1.05) { up = true; break; } }
    bot.setControlState('jump', false);
    if (!up) break;
    try { await bot.placeBlock(bot.blockAt(feet.offset(0, -1, 0)), new Vec3(0, 1, 0)); placed++; } catch { break; }
    for (let t = 0; t < 10 && !bot.entity.onGround; t++) await bot.waitForTicks(1);
    if (!(await holdBlock(bot))) break;
  }
  if (placed) log('pillared up', placed);
  return placed;
}

/** Whether a player stands on narrow ground (a bridge, an edge): few solid blocks round their feet. */
function onNarrow(bot, who) {
  const under = who.position.offset(0, -0.5, 0).floored();
  let n = 0;
  for (let ox = -1; ox <= 1; ox++) for (let oz = -1; oz <= 1; oz++) if (solid(bot, under.offset(ox, 0, oz))) n++;
  return n <= 4;
}

/**
 * Falling into the void (well below the last wide ground, nothing solid under me): an ender pearl thrown back onto
 * that ground saves me. True when one was thrown.
 */
async function pearlClutch(bot, mem) {
  const land = awareness.lastLand;
  if (!land || Date.now() - (mem.pearledAt || 0) < 1500) return false;
  const p = bot.entity.position;
  if (p.y > land.y - 2.5) return false;
  for (let y = Math.floor(p.y) - 1; y > Math.floor(p.y) - 12; y--) if (solid(bot, new Vec3(Math.floor(p.x), y, Math.floor(p.z)))) return false;
  const pearl = items(bot).find((it) => it.name === 'ender_pearl');
  if (!pearl) return false;
  try {
    await bot.equip(pearl, 'hand');
    const eye = bot.entity.position.offset(0, EYE, 0);
    const a = aimPitch('ender_pearl', Math.hypot(land.x - eye.x, land.z - eye.z), land.y - 0.5 - eye.y);
    if (!a) return false;
    await bot.look(Math.atan2(-(land.x - eye.x), -(land.z - eye.z)), a.pitch);
    bot.activateItem();
    mem.pearledAt = Date.now();
    log('falling: ender pearl back to land');
    return true;
  } catch { return false; }
}

/**
 * Ranged answer to a foe in sight, or nothing: a snowball or an egg at one on a bridge or an edge within 18 blocks (its
 * knock-back is a fall), an arrow at one 6-30 away. True when it acted.
 */
async function ranged(bot, foe, mem) {
  const d = bot.entity.position.distanceTo(foe.position);
  if (d >= 4.5 && d <= 18 && throwable(bot) && onNarrow(bot, foe) && (await throwAt(bot, foe, mem))) return true;
  if (d >= 6 && d <= 30 && hasBow(bot)) return shoot(bot, foe);
  return false;
}

/**
 * Remember wide ground (to retreat to), and react to a hit or a foe in sight: fight one close, shoot one far if I have
 * a bow, and leave a narrow bridge for land when hit by someone I cannot reach. True when it acted.
 */
async function reactToThreat(bot, mem) {
  const under = feetCell(bot);
  let ground = 0;
  for (let ox = -1; ox <= 1; ox++) for (let oz = -1; oz <= 1; oz++) if (solid(bot, under.offset(ox, 0, oz))) ground++;
  if (ground >= 6) awareness.lastLand = { x: under.x + 0.5, y: under.y + 1, z: under.z + 0.5 };
  if (await pearlClutch(bot, mem)) return true;
  const hit = Date.now() - awareness.hurtAt < 1500;
  const foe = enemy(bot, { heard: true });
  if (near16(bot, foe)) awareness.threatAt = Date.now();
  const near = foe && bot.entity.position.distanceTo(foe.position) < 8;
  // React to: a hit, a player in sight, or one only heard but close (behind me within 8 blocks: turn and look).
  if (!hit && !(foe && (!foe.heard || near))) return false;
  if (!foe) { await bot.look(bot.entity.yaw + Math.PI, 0); return true; } // hit by someone unseen and unheard: look round
  if (foe.heard) { await bot.lookAt(foe.position.offset(0, 1.5, 0)); return true; } // turn to see them first
  const d = bot.entity.position.distanceTo(foe.position);
  // A foe on a bridge or an edge, out of my reach: knock them off from here (snowball, egg, arrow) before they land.
  if (d > reachOf(bot) && onNarrow(bot, foe) && (await ranged(bot, foe, mem))) return true;
  // Within 10 it is a fight (a hit of mine knocks them back past 6, and they come straight back); farther, an arrow.
  if (d <= 10) { await fight(bot, foe, mem); return true; }
  if (await ranged(bot, foe, mem)) return true;
  if (hit && ground < 6 && awareness.lastLand) {
    log('hit on a bridge: back to land');
    awareness.hurtAt = 0; // the hit that sent me back is answered: a new one stops the walk
    await walkTo(bot, new Vec3(awareness.lastLand.x, awareness.lastLand.y, awareness.lastLand.z), 1, 5000, { interrupt: 'hit' });
    return true;
  }
  return false;
}

/** The solid cell of my island farthest along the way to `target`: where a bridge toward it starts. */
function launchPoint(bot, target) {
  const from = feetCell(bot), to = new Vec3(Math.floor(target.x), from.y, Math.floor(target.z));
  const d = Math.hypot(to.x - from.x, to.z - from.z) || 1;
  let last = from;
  for (let t = 1; t < d; t++) {
    const c = new Vec3(Math.floor(from.x + ((to.x - from.x) * t) / d), from.y, Math.floor(from.z + ((to.z - from.z) * t) / d));
    if (!solid(bot, c)) break;
    last = c;
  }
  return last;
}

/** Get to `target` however: walk if there is ground, else walk to my island's edge facing it and bridge. */
async function travel(bot, target, opts = {}) {
  // A hunt passes false: the player near is the one it is after. Its walks still stop for a hit.
  const interrupt = opts.interrupt === false ? 'hit' : true;
  if (await walkTo(bot, target, 2, 6000, { interrupt })) return 'arrived';
  const start = launchPoint(bot, target);
  await walkTo(bot, start.offset(0.5, 1, 0.5), 0.6, 6000, { interrupt });
  return bridgeTo(bot, target, { ...opts, stopForEnemy: opts.stopForEnemy ?? interrupt === true });
}

async function loot(bot, chest, mem) {
  const key = `${chest.x},${chest.y},${chest.z}`;
  if (mem.looted[key]) return;
  mem.lootTries = mem.lootTries || {};
  // A walk cut short (someone close, no route) leaves the chest to try again; three failed tries and it is let go.
  if (!(await walkTo(bot, chest, 2.5, 8000))) { if ((mem.lootTries[key] = (mem.lootTries[key] || 0) + 1) >= 3) mem.looted[key] = true; return; }
  const block = bot.blockAt(v(chest));
  if (!block || !block.name.includes('chest')) { mem.looted[key] = true; return; }
  try {
    const c = await bot.openContainer(block);
    mem.looted[key] = true;
    const order = (it) => (weaponScore(it) ? 0 : /helmet|chestplate|leggings|boots/.test(it.name) ? 1 : isBlock(it) ? 2 : /golden_apple|pearl/.test(it.name) ? 3 : 4);
    for (const it of c.containerItems().sort((a, b) => order(a) - order(b))) {
      if (threatened(bot, 8)) break; // drop the chest and fight
      try { await c.withdraw(it.name, null, it.count); } catch { /* full, or gone */ }
    }
    try { await c.close(); } catch { /* closed */ }
  } catch (e) { log('chest:', e.message); }
  await wearBestArmour(bot);
  await holdWeapon(bot);
}

/** One beat of a fight: face, close in without walking off an edge, eat when hurt, hit at the cooldown with a W-tap. */
async function fight(bot, foe, mem) {
  if (bot.currentWindow) { try { bot.closeWindow(bot.currentWindow); } catch { /* closed */ } }
  if (bot.health <= 10 && Date.now() - (mem.ate || 0) > 4000) {
    const apple = items(bot).find((it) => it.name === 'golden_apple');
    if (apple) { try { bot.clearControlStates(); await bot.equip(apple, 'hand'); await bot.consume(); mem.ate = Date.now(); log('golden apple'); } catch { /* next time */ } }
  }
  await holdWeapon(bot);
  // Look where they will be when the look arrives, not where they are; farther off, a little more ahead, to cut them
  // off. One look a beat: each costs a reaction time.
  const d = bot.entity.position.distanceTo(foe.position);
  await bot.lookAt(predict(foe, d > 3.5 ? Math.min(0.6, 0.2 + d / 20) : 0.2).offset(0, 1.5, 0));
  // Never chase over the edge. Ground is checked toward the foe (not along my facing: a turn arrives only after the
  // reaction time). On narrow ground -- a bridge -- keep sneaking, never sprint, and step only onto a block that is there.
  const p = bot.entity.position, dx = foe.position.x - p.x, dz = foe.position.z - p.z, len = Math.hypot(dx, dz) || 1;
  const toward = (k) => p.offset((dx / len) * k, -0.5, (dz / len) * k).floored();
  const under = feetCell(bot);
  let ground = 0;
  for (let ox = -1; ox <= 1; ox++) for (let oz = -1; oz <= 1; oz++) if (solid(bot, under.offset(ox, 0, oz))) ground++;
  const narrow = ground < 6;
  const safe = solid(bot, toward(0.8)) && (narrow || solid(bot, toward(1.6)));
  // Ground away from them (for a step back) and to both sides (for a strafe), at one and two blocks.
  const at = (ax, az, k) => p.offset(ax * k, -0.5, az * k).floored();
  const backSafe = solid(bot, at(-dx / len, -dz / len, 1)) && solid(bot, at(-dx / len, -dz / len, 2));
  const sidesSafe = [1, -1].every((s) => solid(bot, at((s * dz) / len, (-s * dx) / len, 1)) && solid(bot, at((s * dz) / len, (-s * dx) / len, 2)));
  bot.setControlState('sneak', narrow);
  // On a one-block bridge with a foe coming: brace first -- ground on the line from them, behind me and before me, so
  // their hit does not put me in the void (once a spot).
  if (narrow && d < 8 && blockCount(bot) > 4) {
    const key = `${under.x},${under.y},${under.z}`;
    if (mem.braced !== key) {
      mem.braced = key;
      if (await holdBlock(bot)) {
        // A hit sends me straight away from them: ground on that line (behind me, and before me) keeps me up.
        const sides = Math.abs(dx) > Math.abs(dz) ? [new Vec3(-Math.sign(dx), 0, 0), new Vec3(Math.sign(dx), 0, 0)] : [new Vec3(0, 0, -Math.sign(dz)), new Vec3(0, 0, Math.sign(dz))];
        for (const s of sides) if (!solid(bot, under.plus(s))) { try { await bot.placeBlock(bot.blockAt(under), s); } catch { /* not here */ } }
        // And a wall behind me, two high, on that ground: a hit cannot push me through it.
        const back = under.plus(sides[0]), up = new Vec3(0, 1, 0);
        for (let h = 0; h < 2; h++) {
          const below = back.offset(0, h, 0);
          if (solid(bot, below) && !solid(bot, below.plus(up))) { try { await bot.placeBlock(bot.blockAt(below), up); } catch { break; } }
        }
        log('braced on the bridge');
        await holdWeapon(bot);
      }
    }
  }
  // Beaten and hurt, with nothing to eat: back away on land (looking at them) and let health come back, rather than
  // trade the last hits. Not on a bridge, and not more than once in a while.
  if (bot.health <= 6 && !items(bot).some((it) => it.name === 'golden_apple') && !narrow && backSafe && d > 2.2 &&
      Date.now() > (mem.retreatUntil || 0) && foePower(mem) > powerOf(myGear(bot))) {
    mem.retreatUntil = Date.now() + 8000;
    log('outmatched and hurt: backing off from', foe.username);
    const away = p.offset((-dx / len) * 7, 0, (-dz / len) * 7);
    await walkTo(bot, away, 2, 2500, { interrupt: false });
    return;
  }
  // Swing from just inside my reach: the other side swings from the edge of theirs, and the first hit on a bridge wins.
  const reach = reachOf(bot) - 0.1;
  const above = foe.position.y - p.y, across = Math.hypot(dx, dz);
  if (above >= 2 && across <= 4 && d > reach && (await pillarUp(bot, Math.min(4, Math.ceil(above - 0.5))))) return;
  if (d <= reach) {
    if (Date.now() - (mem.hit || 0) >= ATTACK_MS) {
      bot.setControlState('left', false); bot.setControlState('right', false);
      bot.setControlState('sprint', false);          // W-tap: a fresh sprint makes the hit a knockback one
      await bot.waitForTicks(1);
      if (safe && !narrow) { bot.setControlState('forward', true); bot.setControlState('sprint', true); }
      try { await bot.attack(foe); mem.hit = Date.now(); mem.hits = (mem.hits || 0) + 1; log('swing at', foe.username, d.toFixed(1)); } catch { /* out of reach now */ }
      await bot.waitForTicks(1);
      bot.setControlState('forward', false);
      bot.setControlState('sprint', false);
      // S-tap: pressed against them, step back so the next hit lands from the edge of my reach (theirs misses more).
      if (d < 2.2 && !narrow && backSafe) { bot.setControlState('back', true); await bot.waitForTicks(3); bot.setControlState('back', false); }
    } else if (!narrow && sidesSafe) {
      // Between hits, strafe: a side-step every half second or so makes me harder to hit and to knock straight back.
      if (Date.now() > (mem.strafeFlip || 0)) { mem.strafe = mem.strafe === 'left' ? 'right' : 'left'; mem.strafeFlip = Date.now() + 450 + Math.random() * 300; }
      bot.setControlState(mem.strafe === 'left' ? 'right' : 'left', false);
      bot.setControlState(mem.strafe, true);
      await bot.waitForTicks(2);
      bot.setControlState(mem.strafe, false);
    } else await bot.waitForTicks(1);
  } else if (safe) {
    bot.setControlState('forward', true);
    if (!narrow) bot.setControlState('sprint', true);
    await bot.waitForTicks(narrow ? 1 : 2);
    bot.setControlState('forward', false);
    bot.setControlState('sprint', false);
  } else {
    bot.clearControlStates();
    // The straight line to them crosses void -- but there may be a way round on land or along a bridge that does not
    // run straight at them. Let the pathfinder walk it first (it uses any ground, bridges included); build only when
    // there is no walking route, and shoot when I can.
    if (await ranged(bot, foe, mem)) return;
    // Close, but the straight line to them crosses void: they are coming to me, or standing at an edge. Hold my
    // ground facing them and swing when they are in reach; a walk round now would turn my back to them for seconds.
    if (d < 6) { await bot.waitForTicks(2); return; }
    if (Date.now() > (mem.noRouteUntil || 0)) {
      const p = foe.position;
      if (await walkTo(bot, new Vec3(p.x, p.y, p.z), 2.5, 2500, { interrupt: false })) return;
      if (bot.entity.position.distanceTo(foe.position) < d - 1) return; // got closer: keep going next beat
      mem.noRouteUntil = Date.now() + 5000;                                // no way round: build, and do not ask again for a while
    }
    if (d < 14) await bridgeTo(bot, foe.position, { stopForEnemy: false, arrive: 2.8 });
  }
}

// ---------------------------------------------------------------------------------------------------------------------
// The planner: which macro move next. A small Monte Carlo tree search over an abstract model of the round.
//
// There is rarely one best next step (two chests opened and good loot already: open the third, or rush the middle
// before the other player gets there?). So the bot estimates: it simulates the rest of the round many times in a fast,
// rough model -- both players moving between their islands and the middle, chests giving random loot, bridges taking
// time and blocks, fights won with a probability that grows with the gear and health difference -- and keeps the
// statistics in a tree (UCT) over its own next moves. What it knows goes into the model: its own gear, health, blocks
// and apples; the gaps it would have to bridge, measured from the blocks; which chests are done; where the other
// player was last seen, what it wore and held, and whether blocks are appearing on its way; and the clock.
// It then picks a move with probability rising with how often the search chose it (not always the top one), and each
// bot draws its own personality at the start, so no two games are played alike.

/** A player's fighting strength: armour points worn, weapon damage, health, golden apples. */
function powerOf({ armour = 0, weapon = 1, hp = 20, apples = 0 }) { return armour * 0.9 + weapon * 1.6 + hp * 0.25 + apples * 2; }

const ARMOUR_POINTS = { helmet: [1, 2, 2, 2, 3, 3], chestplate: [3, 5, 5, 6, 8, 8], leggings: [2, 3, 4, 5, 6, 6], boots: [1, 1, 1, 2, 3, 3] };

const TIER_INDEX = { leather: 0, golden: 1, chainmail: 2, iron: 3, diamond: 4, netherite: 5 };

function armourPoints(names) {
  let p = 0;
  for (const n of names) {
    if (!n) continue;
    const [tier, piece] = [n.split('_')[0], n.split('_').slice(1).join('_')];
    const row = ARMOUR_POINTS[piece];
    if (row && TIER_INDEX[tier] != null) p += row[TIER_INDEX[tier]];
  }
  return p;
}

/** A seeded-enough random number source, so a search can be replayed from its log if needed. */
function rng(seed) { let s = seed >>> 0 || 1; return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296); }

/**
 * The search: UCT over my next two moves, rollouts after. Returns each first move's visits and mean value.
 * Spread over awaits so no step uses more than a few ms of CPU.
 */
async function search(root, model, persona, { iterations = 800, horizon = 150, seed = Date.now() } = {}) {
  const r = rng(seed);
  const nodes = new Map(); // key: moves joined -> { n, w }
  // The game's model: the moves open after a prefix of mine, and a playout of the rest of the round.
  const legalAt = (prefix) => model.legal(root, prefix);
  const rollout = (state, plan, rr, p, h) => model.rollout(state, plan, rr, p, h);
  const firstMoves = legalAt([]);
  if (!firstMoves.length) return [];
  const seconds = new Map(firstMoves.map((m) => [m, legalAt([m])]));
  const stat = (k) => nodes.get(k) || nodes.set(k, { n: 0, w: 0 }).get(k);
  const uct = (parent, child) => (child.n === 0 ? Infinity : child.w / child.n + persona.explore * Math.sqrt(Math.log(parent.n + 1) / child.n));
  const rootStat = stat('');
  let lastYield = Date.now();
  for (let it = 0; it < iterations; it++) {
    const m1 = firstMoves.reduce((a, b) => (uct(rootStat, stat(b)) > uct(rootStat, stat(a)) ? b : a));
    const s1 = stat(m1);
    const opts2 = seconds.get(m1);
    const m2 = opts2.length ? opts2.reduce((a, b) => (uct(s1, stat(`${m1},${b}`)) > uct(s1, stat(`${m1},${a}`)) ? b : a)) : null;
    const value = rollout(root, m2 ? [m1, m2] : [m1], r, persona, horizon);
    rootStat.n++; s1.n++; s1.w += value;
    if (m2) { const s2 = stat(`${m1},${m2}`); s2.n++; s2.w += value; }
    // Yield often: the arena restarts a program that runs 50 ms without awaiting.
    if (Date.now() - lastYield > 15) { await sleep(0); lastYield = Date.now(); }
  }
  return firstMoves.map((m) => ({ move: m, n: stat(m).n, mean: stat(m).w / Math.max(1, stat(m).n) }));
}

/** Choose from the search: more visits, more likely; the temperature (the bot's personality) sets how loosely. */
function choose(results, persona, r = Math.random) {
  const weights = results.map((x) => Math.pow(x.n + 1, 1 / persona.temperature) * (persona.bias[x.move] || 1));
  let total = weights.reduce((a, b) => a + b, 0), x = r() * total;
  for (let i = 0; i < results.length; i++) if ((x -= weights[i]) <= 0) return results[i].move;
  return results[0].move;
}

/**
 * A personality, drawn once per match: how greedy, how bold, how loose in choosing. `biasFor(greed, aggression)`
 * (the game's) leans each move up or down.
 */
function newPersona(biasFor = () => ({}), r = Math.random) {
  const greed = 0.7 + r() * 0.6, aggression = 0.7 + r() * 0.6;
  return {
    temperature: 0.35 + r() * 0.4,           // how far from the search's favourite it may stray
    explore: 0.9 + r() * 0.8,                 // UCT exploration
    nerve: (aggression - 1) * 2,              // how much it trusts its own strength in a fight
    bias: biasFor(greed, aggression),
    greed, aggression,
  };
}

/** Void columns at ground level on the straight way from a to b (an island's own ground and any bridge count as land). */
function gapBetween(bot, a, b) {
  const y = Math.floor(Math.min(a.y, b.y)) - 1, d = Math.hypot(b.x - a.x, b.z - a.z);
  const seen = new Set();
  let air = 0;
  for (let t = 0; t <= d; t += 0.5) {
    const x = Math.floor(a.x + ((b.x - a.x) * t) / d), z = Math.floor(a.z + ((b.z - a.z) * t) / d), k = `${x},${z}`;
    if (seen.has(k)) continue;
    seen.add(k);
    if (!solid(bot, new Vec3(x, y, z))) air++;
  }
  return air;
}

/** My fighting gear as powerOf wants it. */
function myGear(bot) {
  const its = items(bot);
  let worn = [];
  try { worn = (bot.inventory.slots || []).slice(5, 9).map((s) => s && s.name); } catch { /* none */ }
  return { armour: armourPoints(worn), weapon: Math.max(1, ...its.map(weaponScore)), hp: bot.health, apples: its.filter((it) => it.name === 'golden_apple').reduce((n, it) => n + it.count, 0) };
}
/** The last-seen foe's strength (its health unknown: taken as full). */
function foePower(mem) { const f = mem.foe || {}; return powerOf({ armour: f.armour ?? 0, weapon: f.weapon ?? 1, hp: 20 }); }

/** What I know of the other player: last seen where and when, wearing and holding what; blocks seen appearing. */
function trackFoe(bot, mem) {
  const foe = enemy(bot);
  if (!foe) return;
  const eq = [].concat(foe.equipment || []).map((e) => (e && (e.name || e)) || null).filter((n) => typeof n === 'string');
  mem.foe = {
    x: foe.position.x, y: foe.position.y, z: foe.position.z, t: bot.arena.time,
    armour: eq.length ? armourPoints(eq) : mem.foe?.armour ?? null,
    weapon: foe.heldItem ? SWORD[foe.heldItem.name] ?? AXE[foe.heldItem.name] ?? 1 : mem.foe?.weapon ?? null,
  };
}

// House bot for Bed Wars: a strategy program with no AI behind it, on the house bots' core (bots/core.js).
//
// Bed Wars is a race between economy, defence and attack: farm iron at the forge, buy wool and gear at the Item Shop,
// cover your bed with wool, bridge over and break the enemy's bed, then kill the enemy for good. None of these is always
// the right next step (cover the bed first, or rush before the enemy has wool? another sword, or armour?), so the
// planner (core.js: a Monte Carlo tree search over a model of the round) estimates the next move from the real state:
// what I carry, my bed and its cover, the enemy's bed and its cover (read from the world), the gaps to bridge (measured
// from the blocks), what I have seen of the enemy, and the clock. Each bot has its own personality, so games differ.

const BW_MOVES = ['farm', 'buy_wool', 'buy_sword', 'buy_armour', 'defend', 'rush', 'hunt', 'go_home'];
const IRON_PER_S = 1 / 1.5, GOLD_PER_S = 1 / 6, BW_WALK = 4.3, BW_BRIDGE = 1.1;
const RESPAWN_S = 5, BREAK_S = 3, COVER_BREAK_S = 5;

const bwClone = (p) => ({ ...p });

/** Travel in the model: walking where there is ground or a bridge, else bridging with wool. */
function bwTravel(world, p, to) {
  if (p.place === to) return { t: 1 };
  const key = `${p.place}>${to}`, g = world.gaps[key] ?? 15, d = world.dists[key] ?? 40;
  if (g <= 0 || world.bridges[key] || world.bridges[`${to}>${p.place}`]) return { t: d / BW_WALK, to };
  if (p.wool < g) return null;
  return { t: d / BW_WALK + g * BW_BRIDGE, wool: g, bridge: key, to };
}

/** What a move costs and gives in the model, or null when it cannot be done. */
function bwCost(world, p, move) {
  const home = p.place === p.home;
  switch (move) {
    case 'farm': return home ? { t: 8, iron: 8 * IRON_PER_S, gold: 8 * GOLD_PER_S } : null;
    case 'buy_wool': return home && p.iron >= 4 ? { t: 3, iron: -4, woolGain: 16 } : null;
    case 'buy_sword': return home && p.sword < 5 && p.iron >= 10 ? { t: 3, iron: -10, sword: 5 } : home && p.sword < 6 && p.gold >= 7 ? { t: 3, gold: -7, sword: 6 } : null;
    // Armour points worn: leather 7, with chainmail leggings and boots 9, with iron 11 (the shop sells those two).
    case 'buy_armour': return home && p.armour < 9 && p.iron >= 24 ? { t: 3, iron: -24, armour: 9 } : home && p.armour < 11 && p.gold >= 12 ? { t: 3, gold: -12, armour: 11 } : null;
    case 'defend': return home && p.bedAlive && p.cover < 1 && p.wool >= 8 ? { t: 8, woolUse: 8, cover: 1 } : null;
    case 'rush': { const c = p.foeBed() ? bwTravel(world, p, p.away) : null; return c ? { ...c, rush: true } : null; }
    case 'hunt': { const c = bwTravel(world, p, p.target ?? p.away); return c && p.place !== (p.target ?? p.away) ? c : null; }
    case 'go_home': { const c = !home && bwTravel(world, p, p.home); return c || null; }
    default: return null;
  }
}

function bwApply(world, p, move) {
  const c = bwCost(world, p, move);
  if (!c) return null;
  p.busy = world.t + c.t;
  if (c.iron) p.iron += c.iron;
  if (c.gold) p.gold += c.gold;
  if (c.woolGain) p.wool += c.woolGain;
  if (c.woolUse) p.wool -= c.woolUse;
  if (c.wool) p.wool -= c.wool;
  if (c.sword) p.sword = c.sword;
  if (c.armour) p.armour = c.armour;
  if (c.cover) p.cover += c.cover;
  if (c.bridge) world.bridges[c.bridge] = true;
  // Travel ends where it goes when it is done (the playout moves the player then).
  if (c.to) { p.dest = c.to; p.from = p.place; }
  p.rushing = !!c.rush;
  return p;
}

const bwPower = (p) => powerOf({ armour: p.armour, weapon: p.sword, hp: 20, apples: 0 });

/** A player's move in a playout: farm and buy toward a bridge, cover the bed, then rush or hunt; random, but sensible. */
function bwFoeMove(world, f, r) {
  const opts = [];
  const home = f.place === f.home;
  const need = Math.min(64, (world.gaps[`${f.home}>${f.away}`] ?? 30) + 8);
  if (home) {
    if (f.iron >= 4 && f.wool < need) opts.push(['buy_wool', 3]);
    if (f.iron >= 10 && f.sword < 5) opts.push(['buy_sword', 2]);
    if (f.iron >= 24 && f.armour < 9) opts.push(['buy_armour', 1.2]);
    if (f.bedAlive && f.cover < 1 && f.wool >= 8) opts.push(['defend', 1.2]);
    opts.push(['farm', f.wool < need ? 2.5 : 0.8]);
  } else opts.push(['go_home', f.wool < 4 ? 2 : 0.3]);
  opts.push(['rush', f.wool >= need - 8 ? 3 : 0.3], ['hunt', world.t > 100 ? 1.2 : 0.3]);
  const legal = opts.filter(([m]) => bwCost(world, f, m));
  let total = legal.reduce((s, o) => s + o[1], 0), x = r() * total;
  for (const [m, w] of legal) if ((x -= w) <= 0) return m;
  return legal[0] ? legal[0][0] : null;
}

/** A meeting: the loser respawns at home with nothing carried (bed standing) or is out. */
function bwFight(world, a, b, r, persona) {
  const pA = 1 / (1 + Math.exp(-(bwPower(a) - bwPower(b) + (a.isMe ? persona.nerve : -persona.nerve)) / 3));
  const loser = r() < pA ? b : a;
  world.t += 6;
  if (!loser.bedAlive) loser.out = true;
  else Object.assign(loser, { place: loser.home, dest: null, busy: world.t + RESPAWN_S, wool: 0, iron: 0, gold: 0, sword: 4, rushing: false });
}

/** A playout: both act when free; rushes break beds, meetings fight; ends with an elimination, the clock or the horizon. */
function bwRollout(root, plan, r, persona, horizon) {
  const world = { ...root, bridges: { ...root.bridges } };
  const me = bwClone(root.me), foe = bwClone(root.foe);
  me.isMe = true; me.foeBed = () => foe.bedAlive; foe.foeBed = () => me.bedAlive;
  let i = 0;
  const end = Math.min(root.t + horizon, root.limit);
  while (world.t < end) {
    if (me.out) return -1;
    if (foe.out) return 1;
    for (const p of [me, foe]) if (p.dest && p.busy <= world.t) { p.place = p.dest; p.dest = null; }
    // A rush that reached the enemy base with nobody there breaks the bed (through its cover).
    for (const [p, q] of [[me, foe], [foe, me]]) {
      if (p.rushing && p.place === p.away && q.bedAlive && q.place !== q.home) { q.bedAlive = false; p.rushing = false; p.busy += BREAK_S + q.cover * COVER_BREAK_S; }
    }
    // Meeting: the same place, or crossing each other on the way.
    const crossing = me.dest && foe.dest && me.dest === foe.from && foe.dest === me.from;
    if (me.place === foe.place || crossing) { if (crossing) { me.place = foe.place = 'mid'; me.dest = foe.dest = null; } bwFight(world, me, foe, r, persona); }
    if (me.out) return -1;
    if (foe.out) return 1;
    const actor = me.busy <= foe.busy ? me : foe;
    world.t = Math.max(world.t, actor.busy);
    if (world.t >= end) break;
    me.target = foe.place; foe.target = me.place;
    if (actor === me) {
      let move = plan[i++];
      if (!move) move = bwFoeMove(world, me, r);
      if (!move || !bwApply(world, me, move)) me.busy = world.t + 3;
    } else {
      const m = bwFoeMove(world, foe, r);
      if (!m || !bwApply(world, foe, m)) foe.busy = world.t + 3;
    }
  }
  if (world.t >= root.limit) return 0;
  // Not decided by the horizon: how it stands, worth less the less time is left to turn it into a win (a tie is 0).
  const beds = (me.bedAlive ? 1 : -1) - (foe.bedAlive ? 1 : -1);
  return Math.tanh((bwPower(me) - bwPower(foe) + persona.nerve) / 6 + beds * 0.4) * 0.7 * Math.max(0, (root.limit - world.t) / root.limit);
}

const BEDWARS_MODEL = {
  legal(root, prefix) {
    const world = { ...root, bridges: { ...root.bridges } };
    const me = bwClone(root.me);
    me.foeBed = () => root.foe.bedAlive;
    for (const m of prefix) { bwApply(world, me, m); if (me.dest) { me.place = me.dest; me.dest = null; } }
    return BW_MOVES.filter((m) => bwCost(world, me, m));
  },
  rollout: bwRollout,
};
const bedwarsBias = (greed, aggression) => ({ farm: greed, buy_wool: 1, buy_sword: 1, buy_armour: greed, defend: 2 - aggression, rush: aggression, hunt: aggression, go_home: 1 });

// --- the real game ---------------------------------------------------------------------------------------------------

const bedAt = (bot, base) => { const b = bot.blockAt(v(base.bed.head)); return !!b && /bed/.test(b.name); };
/** The bed's cover cells: on top of both halves, and round them at bed level. */
function coverCells(base) {
  const f = v(base.bed.foot), h = v(base.bed.head), dir = h.minus(f);
  const side = new Vec3(dir.z, 0, -dir.x);
  const cells = [f.offset(0, 1, 0), h.offset(0, 1, 0), f.minus(dir), h.plus(dir), f.plus(side), f.minus(side), h.plus(side), h.minus(side)];
  return { cells, dir, f, h };
}
const coverCount = (bot, base) => coverCells(base).cells.filter((c) => solid(bot, c)).length;

async function buy(bot, base, key) {
  if (!(await walkTo(bot, v(base.shop), 2, 8000))) return false;
  const npc = bot.nearestEntity((e) => e.displayName === 'Item Shop' && (!e.team || e.team === base.team));
  if (!npc) return false;
  try {
    const w = await bot.activateEntity(npc);
    const win = w || bot.currentWindow;
    const slot = win ? win.slots.findIndex((s) => s && s.key === key) : -1;
    if (slot < 0) { log('no offer', key); return false; }
    await bot.clickWindow(slot, 0, 0);
    log('bought', key);
    return true;
  } catch (e) { log('shop:', e.message); return false; } finally { try { if (bot.currentWindow) bot.closeWindow(bot.currentWindow); } catch { /* closed */ } }
}

async function farm(bot, base, seconds) {
  if (!(await walkTo(bot, v(base.forge), 0.6, 8000))) return;
  for (let i = 0; i < seconds * 4; i++) {
    if (threatened(bot)) return; // hit, or someone close (seen or only heard): stop farming and turn to fight
    await bot.waitForTicks(5);
  }
}

async function coverBed(bot, base) {
  const { cells, dir, f } = coverCells(base);
  // Stand behind the bed (its foot side), in reach of every cover cell.
  const stand = f.minus(dir.scaled ? dir.scaled(2) : new Vec3(dir.x * 2, 0, dir.z * 2));
  await walkTo(bot, stand.offset(0.5, 0, 0.5), 1, 6000);
  // Sides first (on the ground), then the tops (against the bed, or a side placed).
  for (const c of [...cells.slice(2), ...cells.slice(0, 2)]) {
    if (threatened(bot)) return;
    if (solid(bot, c)) continue;
    if (!(await holdBlock(bot))) return;
    const refs = [[new Vec3(0, -1, 0)], [new Vec3(1, 0, 0)], [new Vec3(-1, 0, 0)], [new Vec3(0, 0, 1)], [new Vec3(0, 0, -1)]];
    for (const [off] of refs) {
      const ref = c.plus(off);
      const b = bot.blockAt(ref);
      if (!b || b.name === 'air' || (b.boundingBox !== 'block' && !/bed/.test(b.name))) continue;
      try { await bot.lookAt(ref.offset(0.5, 0.5, 0.5)); await bot.placeBlock(b, new Vec3(-off.x, -off.y, -off.z)); break; } catch { /* the next face */ }
    }
  }
  log('bed covered:', coverCount(bot, base), 'of 8');
}

async function breakBed(bot, base) {
  const { cells, dir, h } = coverCells(base);
  // Come at it from the middle's side: the bed's head faces the middle.
  const r = await travel(bot, h.plus(new Vec3(dir.x * 2, 0, dir.z * 2)).offset(0.5, 1, 0.5), { arrive: 2 });
  if (r !== 'arrived') { log('rush:', r); return; }
  for (let tries = 0; tries < 12 && bedAt(bot, base); tries++) {
    if (Date.now() - awareness.hurtAt < 1500) return; // hit while breaking it: fight first
    try { await bot.dig(bot.blockAt(h)); } catch (e) {
      // Covered: dig the cover nearest me first.
      const c = cells.filter((x) => solid(bot, x)).sort((a, b) => bot.entity.position.distanceTo(a) - bot.entity.position.distanceTo(b))[0];
      if (!c) break;
      try { await bot.dig(bot.blockAt(c)); } catch { await bot.waitForTicks(4); }
    }
  }
  log(bedAt(bot, base) ? 'the bed still stands' : 'BROKE THE BED');
}

/** The real state, as the Bed Wars model sees it. */
function bwState(bot, mem, B) {
  const t = bot.arena.time || 0, limit = bot.arena.timeLimit || 600;
  const place = (p) => {
    const d = { own: p.xzDistanceTo(B.own), mid: p.xzDistanceTo(B.mid), foe: p.xzDistanceTo(B.foe) };
    return Object.entries(d).sort((a, b) => a[1] - b[1])[0][0];
  };
  const worn = [5, 6, 7, 8].map((i) => bot.inventory.slots[i]?.name).filter(Boolean);
  const me = {
    home: 'own', away: 'foe', place: place(bot.entity.position), busy: t, iron: bot.inventory.count('iron_ingot'), gold: bot.inventory.count('gold_ingot'),
    wool: blockCount(bot), sword: Math.max(1, ...items(bot).map(weaponScore)), armour: armourPoints(worn), bedAlive: bedAt(bot, B.mine), cover: coverCount(bot, B.mine) >= 6 ? 1 : 0,
  };
  const seen = mem.foe && t - mem.foe.t < 25 ? mem.foe : null;
  const foe = {
    home: 'foe', away: 'own', place: seen ? place(new Vec3(seen.x, seen.y, seen.z)) : t < 30 ? 'foe' : 'mid', busy: t + 2,
    iron: Math.min(20, t * IRON_PER_S * 0.4), gold: 0, wool: t < 15 ? 0 : 24, sword: seen?.weapon ?? (t < 20 ? 4 : 5), armour: seen?.armour ?? (t < 90 ? 7 : 12),
    bedAlive: bedAt(bot, B.theirsBase), cover: coverCount(bot, B.theirsBase) >= 6 ? 1 : 0,
  };
  const gaps = {}, dists = {};
  for (const [a, b] of [['own', 'mid'], ['mid', 'foe'], ['own', 'foe']]) {
    const g = gapBetween(bot, B[a], B[b]), d = B[a].xzDistanceTo(B[b]);
    gaps[`${a}>${b}`] = gaps[`${b}>${a}`] = g; dists[`${a}>${b}`] = dists[`${b}>${a}`] = d;
  }
  return { t, limit, me, foe, gaps, dists, bridges: {} };
}

async function bwPerform(bot, mem, move, B) {
  switch (move) {
    case 'farm': await farm(bot, B.mine, 8); return;
    case 'buy_wool': await buy(bot, B.mine, 'wool'); return;
    case 'buy_sword': await buy(bot, B.mine, bot.inventory.count('iron_ingot') >= 10 ? 'stone_sword' : 'iron_sword'); await holdWeapon(bot); return;
    case 'buy_armour': await buy(bot, B.mine, bot.inventory.count('iron_ingot') >= 24 ? 'chain_armor' : 'iron_armor'); return;
    case 'defend': await coverBed(bot, B.mine); return;
    case 'rush': await breakBed(bot, B.theirsBase); return;
    case 'hunt': {
      const seen = mem.foe && bot.arena.time - mem.foe.t < 25 ? new Vec3(mem.foe.x, mem.foe.y, mem.foe.z) : B.foe;
      log('hunting:', await travel(bot, seen, { arrive: 3, interrupt: false }));
      return;
    }
    case 'go_home': log('home:', await travel(bot, v(B.mine.spawn), { arrive: 3 })); return;
    default: await bot.waitForTicks(10);
  }
}

async function main(bot, mem) {
  mem.persona = mem.persona || newPersona(bedwarsBias);
  bot.clearControlStates();
  log('started; team', bot.arena.me && bot.arena.me.team, 'persona', JSON.stringify({ greed: +mem.persona.greed.toFixed(2), aggression: +mem.persona.aggression.toFixed(2), temperature: +mem.persona.temperature.toFixed(2) }));
  bot.on('death', () => log('died'));
  watchForHits(bot);
  for (;;) {
    try {
      const me = bot.arena.me || {};
      if (bot.arena.phase !== 'playing' || me.alive === false || me.respawning) { await bot.waitForTicks(5); continue; }
      const L = bot.arena.landmarks || {};
      const bases = L.bases || [];
      const mine = bases.find((b) => b.team === me.team), theirs = bases.find((b) => b.team !== me.team);
      if (!mine || !theirs) { await bot.waitForTicks(10); continue; }
      const here = bot.entity.position;
      trackFoe(bot, mem);
      const foe = enemy(bot);
      // Reflexes: a hit or a foe in sight (reactToThreat), a foe close by, or at my bed while I am there to defend it.
      if (await reactToThreat(bot, mem)) continue;
      const atMyBed = foe && foe.position.distanceTo(v(mine.bed.head)) < 7 && here.distanceTo(v(mine.bed.head)) < 16;
      if (foe && (here.distanceTo(foe.position) <= 8 || atMyBed)) { await fight(bot, foe, mem); continue; }

      const mid = L.middle ? v(L.middle) : new Vec3(0.5, 31, 0.5);
      const B = { mine, theirsBase: theirs, own: v(mine.spawn), foe: v(theirs.spawn), mid };
      const root = bwState(bot, mem, B);
      const results = await search(root, BEDWARS_MODEL, mem.persona, { horizon: 180 });
      if (!results.length) { await farm(bot, mine, 4); continue; }
      const move = choose(results, mem.persona);
      log(`plan ${move} | ${results.sort((a, b) => b.n - a.n).map((x) => `${x.move} ${x.n} ${x.mean >= 0 ? '+' : ''}${x.mean.toFixed(2)}`).join(', ')} | me ${root.me.place} i${root.me.iron} w${root.me.wool} s${root.me.sword} a${root.me.armour} bed${root.me.bedAlive ? root.me.cover : 'X'}; foe bed${root.foe.bedAlive ? root.foe.cover : 'X'}`);
      await bwPerform(bot, mem, move, B);
      await bot.waitForTicks(1);
    } catch (e) {
      log('error:', e.message);
      bot.clearControlStates();
      await bot.waitForTicks(4);
    }
  }
}

module.exports = { main };
